import ("encoding/binary"; "net")

func sendMsg(conn net.Conn, data []byte) error {
    var hdr [4]byte
    binary.BigEndian.PutUint32(hdr[:], uint32(len(data)))
    if _, err := conn.Write(hdr[:]); err != nil { return err }
    _, err := conn.Write(data)
    return err
}

