// read_exactly:一定读满 n 字节才返回。这是重点。
int read_n(int fd, char *buf, size_t n) {
    size_t got = 0;
    while (got < n) {
        ssize_t r = recv(fd, buf + got, n - got, 0);
        if (r == 0) return 0;               // 对端关闭
        if (r < 0) { if (errno==EINTR) continue; return -1; }
        got += r;
    }
    return 1;
}
// 读一条消息:先读 4 字节长度,再按长度读内容
int recv_msg(int fd, char *out, uint32_t *len) {
    uint32_t nlen;
    if (read_n(fd, (char*)&nlen, 4) <= 0) return -1;
    *len = ntohl(nlen);
    return read_n(fd, out, *len);
}

