import struct

def read_n(sock, n: int) -> bytes:
    buf = b''
    while len(buf) < n:
        chunk = sock.recv(n - len(buf))
        if not chunk:                # 对端关闭
            raise ConnectionError('对端在读完前关闭了')
        buf += chunk
    return buf

def recv_msg(sock) -> bytes:
    (length,) = struct.unpack('>I', read_n(sock, 4))
    return read_n(sock, length)

