import ("encoding/binary"; "io"; "net")

func recvMsg(conn net.Conn) ([]byte, error) {
    var hdr [4]byte
    if _, err := io.ReadFull(conn, hdr[:]); err != nil {  // 就是 read_n
        return nil, err
    }
    n := binary.BigEndian.Uint32(hdr[:])
    data := make([]byte, n)
    _, err := io.ReadFull(conn, data)                     // 循环读够
    return data, err
}
